    payload = JSON_SET(
        payload,
        '$.grades',
        JSON_ARRAY(
            'Grade 6',
            'Grade 7',
            'Grade 8',
            'Grade 9',
            'Grade 10',
            'Grade 11',
            'Grade 12'
